CREATE TABLE `evacuation_indicator` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `evacuation_date` date NOT NULL,
  `evacuated_to` varchar(100) DEFAULT NULL,
  `beneficiary_id` bigint NOT NULL,
  `submitted_time` timestamp NOT NULL,
  `evacuated_from_settlement_id` bigint DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `beneficiary_id` (`beneficiary_id`),
  KEY `fk_evac_from_settlement` (`evacuated_from_settlement_id`),
  CONSTRAINT `evacuation_indicator_ibfk_1` FOREIGN KEY (`beneficiary_id`) REFERENCES `beneficiary` (`id`),
  CONSTRAINT `fk_evac_from_settlement` FOREIGN KEY (`evacuated_from_settlement_id`) REFERENCES `settlements` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=3683 DEFAULT CHARSET=utf8mb3;
